{
  "propositions": [
    {
      "id": "P1",
      "proposition": "The replacement of Tennessee Code Annotated § 55-8-151(c)(2) requires an LEA that installs exterior school-bus cameras under subdivision (c)(1) to enter into a memorandum of understanding with local law enforcement covering at least camera-evidence review and overall enforcement.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "shall enter into a memorandum of understanding with local law\n\n enforcement that includes, but is not limited to, the review of evidence from a camera\n\n and overall enforcement."
    },
    {
      "id": "P2",
      "proposition": "Unless otherwise authorized by law, only POST-certified or state-commissioned law enforcement officers, including school resource officers as defined in § 49-6-4202, may review camera evidence to determine whether a violation of subdivision (a)(1) occurred.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "Unless otherwise authorized by law, only POST-certified or\n\n state-commissioned law enforcement officers, including school resource officers, as\n\n defined in § 49-6-4202, are authorized to review evidence from a camera to determine\n\n whether a violation of subdivision (a)(1) has occurred."
    },
    {
      "id": "P3",
      "proposition": "In addition to, and without limiting, the required memorandum of understanding, an LEA may authorize school security personnel to review camera evidence to determine whether a violation of subdivision (a)(1) occurred.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "an LEA may authorize school security personnel to\n\n review evidence from a camera to determine whether a violation of subdivision (a)(1)\n\n has occurred."
    },
    {
      "id": "P4",
      "proposition": "Using school safety personnel does not prohibit or restrict an LEA from entering into or maintaining the memorandum of understanding with a law enforcement agency; both review processes may operate concurrently.",
      "importance": "supporting",
      "section": "SECTION 1",
      "source_quote": "and both\n\n review processes may be used concurrently."
    },
    {
      "id": "P5",
      "proposition": "For subdivision (c)(2)(B), “school safety personnel” means a school safety officer, school resource officer, or other individual employed or contracted by an LEA whose duties include student safety or campus security.",
      "importance": "supporting",
      "section": "SECTION 1",
      "source_quote": "\"school safety personnel\" means a school safety officer, school resource officer, or other\n\n individual employed or contracted by an LEA whose duties include student safety or\n\n campus security."
    },
    {
      "id": "P6",
      "proposition": "The act takes effect upon becoming law.",
      "importance": "supporting",
      "section": "SECTION 2",
      "source_quote": "This act takes effect upon becoming a law, the public welfare requiring it."
    }
  ]
}
